mastodon.before_sql:
-- Mastodon's id default, which the app creates itself (lib/mastodon/snowflake.rb) and db/schema.rb does not hold: the time in milliseconds shifted two bytes, and a per-table sequence in those two bytes.
CREATE OR REPLACE FUNCTION timestamp_id(table_name text) RETURNS bigint AS $$
DECLARE
  time_part bigint;
  sequence_base bigint;
  tail bigint;
BEGIN
  time_part := (((date_part('epoch', now()) * 1000))::bigint << 16);
  sequence_base := ('x' || substr(md5(table_name || 'orm-generators-examples' || time_part::text), 1, 4))::bit(16)::bigint;
  tail := ((sequence_base + nextval(table_name || '_id_seq')) & 65535);
  RETURN time_part | tail;
END
$$ LANGUAGE plpgsql VOLATILE;

mastodon.after_sql:
-- The sequences timestamp_id() draws on, which the app creates beside each table (Mastodon::Snowflake.ensure_id_sequences_exist).
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema = 'public' AND column_name = 'id' AND column_default LIKE 'timestamp_id(%' LOOP
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I', t || '_id_seq');
  END LOOP;
END
$$;
